  final List<String> path;

  /// Groups shown closed, each one light.
  final List<UniverseGroup> groups;

  /// The owner first, then the one stood at, then the nearest and most
  /// active.
  final List<UniversePerson> people;

  /// Public acts between people, newest first.
  final List<UniverseLine> lines;

  /// People the node knows who didn't fit.
  final PlatformInt64 morePeople;
  final List<UniverseMachine> machines;
  final NetworkTotals? network;

  /// Cells of the public sky, each many people drawn as one light.
  final List<SkyCell> sky;

  const UniverseSnapshot({
    required this.version,
    required this.level,
    required this.region,
    required this.path,
    required this.groups,
    required this.people,
    required this.lines,
    required this.morePeople,
    required this.machines,
    this.network,
    required this.sky,
  });

  @override
  int get hashCode =>
      version.hashCode ^
      level.hashCode ^
      region.hashCode ^
      path.hashCode ^
      groups.hashCode ^
      people.hashCode ^
      lines.hashCode ^
      morePeople.hashCode ^
      machines.hashCode ^
      network.hashCode ^
      sky.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UniverseSnapshot &&
          runtimeType == other.runtimeType &&
          version == other.version &&
          level == other.level &&
          region == other.region &&
          path == other.path &&
          groups == other.groups &&
          people == other.people &&
          lines == other.lines &&
          morePeople == other.morePeople &&
          machines == other.machines &&
          network == other.network &&
          sky == other.sky;
}

class UnsentFile {
  final String path;
  final PlatformInt64 size;

  const UnsentFile({required this.path, required this.size});

  @override
  int get hashCode => path.hashCode ^ size.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UnsentFile &&
          runtimeType == other.runtimeType &&
          path == other.path &&
          size == other.size;
}

/// A post that didn't finish sending, kept on the phone until the node
/// publishes it or the owner discards it.
class UnsentPost {
  final String text;
  final List<UnsentFile> files;

  /// When it was started (RFC 3339).
  final String started;

  const UnsentPost({
    required this.text,
    required this.files,
    required this.started,
  });

  @override
  int get hashCode => text.hashCode ^ files.hashCode ^ started.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UnsentPost &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          files == other.files &&
          started == other.started;
}
